ALTER FUNCTION public.active_school_id() SET SCHEMA private;
ALTER FUNCTION public.school_role() SET SCHEMA private;
ALTER FUNCTION public.shares_active_school(uuid) SET SCHEMA private;
ALTER FUNCTION public.guard_school_links() SET SCHEMA private;
REVOKE ALL ON FUNCTION private.active_school_id() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION private.active_school_id() TO authenticated,service_role;
REVOKE ALL ON FUNCTION private.school_role() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION private.school_role() TO authenticated,service_role;
REVOKE ALL ON FUNCTION private.shares_active_school(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION private.shares_active_school(uuid) TO authenticated;
REVOKE ALL ON FUNCTION private.guard_school_links() FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.active_school_id() RETURNS uuid LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT private.active_school_id() $$;
REVOKE ALL ON FUNCTION public.active_school_id() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.active_school_id() TO authenticated,service_role;
CREATE FUNCTION public.school_role() RETURNS text LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT private.school_role() $$;
REVOKE ALL ON FUNCTION public.school_role() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.school_role() TO authenticated,service_role;
CREATE FUNCTION public.shares_active_school(_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT private.shares_active_school(_user) $$;
REVOKE ALL ON FUNCTION public.shares_active_school(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.shares_active_school(uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.validate_membership() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION private.is_admin(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role='super_admin') OR EXISTS(SELECT 1 FROM public.school_memberships WHERE user_id=_user_id AND school_id=private.active_school_id() AND status='active' AND role='school_manager') $$;
CREATE OR REPLACE FUNCTION private.staff_teaches_class(_class_name text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT private.school_role()='staff' AND EXISTS(SELECT 1 FROM public.teaching_assignments WHERE school_id=private.active_school_id() AND lower(class_name)=lower(_class_name) AND teacher_id=auth.uid()) $$;
CREATE OR REPLACE FUNCTION private.staff_teaches_admission(_admission_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.admissions WHERE id=_admission_id AND school_id=private.active_school_id() AND private.staff_teaches_class(class_admitted)) $$;
CREATE OR REPLACE FUNCTION private.guard_school_links() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE linked uuid; BEGIN IF TG_OP='UPDATE' AND NEW.school_id IS DISTINCT FROM OLD.school_id THEN RAISE EXCEPTION 'School ownership cannot be changed'; END IF; IF TG_TABLE_NAME IN ('staff_schedules','staff_performance','finance_payroll') THEN linked:=NEW.staff_id; ELSIF TG_TABLE_NAME IN ('teaching_assignments','class_teachers') THEN linked:=NEW.teacher_id; END IF; IF linked IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.school_memberships WHERE user_id=linked AND school_id=NEW.school_id AND status='active') THEN RAISE EXCEPTION 'Person is not an active member of this school'; END IF; RETURN NEW; END $$;